#!/usr/bin/env node
// Generate what Codex and opencode read from what Claude Code reads. (#233, #249)
//
// `.claude/` is the one source. Codex reads skills only from `.agents/skills/`, so without a copy
// there it sees none of this repository's skills (0 in `skills/list` at 6512ac9, measured), and
// opencode lists either copy of a same-named pair, by a race. The copies are files, not symlinks,
// because the product owner's colleagues work on Windows.
//
// Usage:
//   node scripts/gen-agent-files.mjs           write every generated file and scripts/agent-files.json
//   node scripts/gen-agent-files.mjs --check   exit 1, naming each difference, if anything has drifted
//
// Never edit a generated file: edit its source and re-run this. Every skill under .claude/skills/
// is copied byte for byte (the gopnik ones stay identical to upstream, scripts/gopnik-upstream.lock.json).
// The root AGENTS.md is CLAUDE.md's Backchannel section plus the two rules that are not scoped to
// paths, embedded whole: Codex reads every AGENTS.md from the git root down and leaves `@path`
// imports as text, and opencode reads the root AGENTS.md in place of CLAUDE.md once one exists.
// Claude Code does not read it, so nothing is loaded twice (#250, ADR 0032).
// Nothing is generated under frontend/, whose AGENTS.md and CLAUDE.md belong to Next.js.
//
// Files are listed through git (tracked, plus untracked that .gitignore does not exclude), so an
// ignored `.DS_Store` never becomes a source. A file under `.agents/` that nothing generates is
// drift, and this script never deletes one it did not write: `npx skills add` and Codex plugins
// put files there too, and an untracked file deleted is gone.
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const LIST = 'scripts/agent-files.json';
// Every directory a generated file may live in.
export const GENERATED_ROOTS = ['.agents', '.opencode/command', '.opencode/commands'];

// The files git would commit under a directory, relative to the repository, with `/` separators.
function gitFiles(repo, dir) {
  const out = execFileSync('git', ['-C', repo, 'ls-files', '-z', '--cached', '--others', '--exclude-standard', '--', dir], { encoding: 'utf8' });
  return [...new Set(out.split('\0').filter(Boolean))].filter((f) => fs.existsSync(path.join(repo, f)) || isLink(repo, f)).sort();
}
const isLink = (repo, f) => { try { return fs.lstatSync(path.join(repo, f)).isSymbolicLink(); } catch { return false; } };
const isFile = (repo, f) => { try { return fs.lstatSync(path.join(repo, f)).isFile(); } catch { return false; } };

// The root AGENTS.md: CLAUDE.md's section, every rule that is not scoped to paths embedded whole, an
// index of the scoped ones, and the line that ends it, which a harness that cut the file short would
// not show. Every unscoped rule is found, not listed: a new one is embedded the day it is added,
// because Claude Code loads it at every session start (#251's adversary).
export const NOT_DELIVERED = 'scripts/agent-files-not-delivered.json';
export const AGENTS_END = '<!-- END:backchannel-agents-md -->';
const BACKCHANNEL = '## Backchannel — read this first';
const FIRST = ['.claude/rules/workflow.md', '.claude/rules/testing.md'];
const readLf = (repo, f) => fs.readFileSync(path.join(repo, f), 'utf8').replace(/\r\n/g, '\n');
const SCOPE = /^---\npaths:\n((?:\s+- .+\n)+)---\n/;

// The scoped rules, from their front matter: path -> globs. Not embedded: Claude Code loads them only
// for the paths they name, and Codex would load them for everything.
export function scopedRules(repo = REPO) {
  return gitFiles(repo, '.claude/rules').filter((f) => f.endsWith('.md')).flatMap((f) => {
    const m = SCOPE.exec(readLf(repo, f));
    return m ? [[f, [...m[1].matchAll(/- "?([^"\n]+)"?/g)].map((g) => g[1])]] : [];
  });
}

// The rules every session loads: workflow.md and testing.md first, then any other, by name.
export function unscopedRules(repo = REPO) {
  const all = gitFiles(repo, '.claude/rules').filter((f) => f.endsWith('.md') && !SCOPE.test(readLf(repo, f)));
  return [...FIRST.filter((f) => all.includes(f)), ...all.filter((f) => !FIRST.includes(f))];
}

export const agentsSources = (repo = REPO) => ['CLAUDE.md', ...unscopedRules(repo)];

function agentsMd(repo) {
  const claude = readLf(repo, 'CLAUDE.md');
  const at = claude.indexOf(BACKCHANNEL);
  if (at < 0) throw new Error(`CLAUDE.md has no "${BACKCHANNEL}" section; the root AGENTS.md is built from it`);
  const scoped = scopedRules(repo).map(([f]) => f);
  return Buffer.from([
    `<!-- Generated by scripts/gen-agent-files.mjs from ${agentsSources(repo).join(', ')}, and the front matter of ${scoped.join(', ')}. Edit those and re-run it; never this file. -->`,
    '# Backchannel: instructions for coding agents',
    claude.slice(at).trimEnd(),
    ...unscopedRules(repo).map((f) => readLf(repo, f).trimEnd()),
    index(repo),
    AGENTS_END,
  ].join('\n\n') + '\n', 'utf8');
}

// frontend/AGENTS.md is named too: Codex started at the root never reads it.
function index(repo) {
  const rows = scopedRules(repo).map(([f, globs]) => `| \`${f}\` | ${globs.map((g) => `\`${g}\``).join(', ')} |`);
  return [
    '## Rules scoped to paths: open the file before you read or edit what it governs',
    'Claude Code loads these on its own when a file under their paths is read. Codex and opencode do not, so open the rule yourself before reading or editing a file it names.',
    ['| rule | governs |', '| --- | --- |', ...rows,
      '| `frontend/AGENTS.md` | `frontend/**` (Next.js 16\'s own notes; Codex started at the root never reads it) |'].join('\n'),
  ].join('\n\n');
}

// The commands become skills for Codex and opencode, and commands for opencode (#252). Codex has no
// project commands: `$work 42` names the skill and injects its body. In Codex `$issue` is the mention
// of the skill that opens issues, so the skills carry no `$issue`; the number is written N. opencode's
// commands put the argument where the command had it, as `$1`, and append free text to `issue`,
// which has no placeholder. `issue` creates GitHub issues, so it is never invoked implicitly: Codex
// lists it only when named (`allow_implicit_invocation: false`), and opencode asks first (`opencode.json`).
const COMMANDS = '.claude/commands';
const NO_IMPLICIT = ['issue'];

function command(repo, f) {
  const text = fs.readFileSync(path.join(repo, f), 'utf8').replace(/\r\n/g, '\n');
  const m = /^---\n([\s\S]*?)\n---\n/.exec(text);
  if (!m) throw new Error(`${f} has no front matter`);
  const description = /^description:\s*(.+)$/m.exec(m[1])?.[1];
  if (!description) throw new Error(`${f} has no description`);
  return { name: path.basename(f, '.md'), description, body: text.slice(m[0].length).replace(/^\n+/, '') };
}

// A command names its siblings as Claude Code invokes them (`/critique 42`). A skill names them as Codex
// does (`$critique 42`); opencode's commands keep the slash, which is how opencode invokes them too.
const asSkill = (body) => body.replace(/`\/(critique|issue|work)\b/g, '`$$$1');

function commandFiles(repo) {
  const out = [];
  for (const f of gitFiles(repo, COMMANDS).filter((f) => f.endsWith('.md'))) {
    const { name, description, body } = command(repo, f);
    const numbered = body.includes('$issue');
    const skill = [
      `---\nname: ${name}\ndescription: ${description}\n---\n`,
      `<!-- Generated by scripts/gen-agent-files.mjs from ${f}. Edit that and re-run it; never this file. -->\n`,
      numbered ? 'The issue number comes with the request that invoked this skill, as in `$' + name + ' 42`. It is written **N** below.\n' : '',
      asSkill(numbered ? body.replaceAll('**$issue**', '**N**').replaceAll('$issue', 'N') : body),
    ].join('\n');
    out.push([`.agents/skills/${name}/SKILL.md`, f, skill]);
    if (NO_IMPLICIT.includes(name)) {
      out.push([`.agents/skills/${name}/agents/openai.yaml`, f,
        `# Generated by scripts/gen-agent-files.mjs from ${f}. ${name} acts on GitHub, so Codex loads it only when it is named.\npolicy:\n  allow_implicit_invocation: false\n`]);
    }
    const cmd = [
      `---\ndescription: ${description}\n---\n`,
      `<!-- Generated by scripts/gen-agent-files.mjs from ${f}. Edit that and re-run it; never this file. -->\n`,
      numbered ? body.replaceAll('$issue', '$1') : body,
    ].join('\n');
    out.push([`.opencode/command/${name}.md`, f, cmd]);
  }
  return out;
}

// What should exist: generated path -> { source, content }. A source is a path, or a list of them.
export function plan(repo = REPO) {
  const out = new Map();
  out.set('AGENTS.md', { source: [...agentsSources(repo), ...scopedRules(repo).map(([f]) => f)], content: agentsMd(repo) });
  for (const [target, source, text] of commandFiles(repo)) out.set(target, { source, content: Buffer.from(text, 'utf8') });
  for (const source of gitFiles(repo, '.claude/skills')) {
    if (!isFile(repo, source)) throw new Error(`${source} is not a regular file; a skill is copied as files, never as links`);
    out.set(source.replace(/^\.claude\/skills\//, '.agents/skills/'), { source, content: fs.readFileSync(path.join(repo, source)) });
  }
  return out;
}

export function listOf(files) {
  return `${JSON.stringify({
    comment: 'Generated by scripts/gen-agent-files.mjs. Each key is generated from its value; edit the value and re-run the script, never the key. (#233)',
    files: Object.fromEntries([...files].map(([target, { source }]) => [target, source])),
  }, null, 2)}\n`;
}

// Line endings are normalized, so a Windows checkout with core.autocrlf compares equal.
export const lf = (b) => b.toString('utf8').replace(/\r\n/g, '\n');

// Files under the generated roots that the plan does not produce.
function strays(repo, files) {
  return GENERATED_ROOTS.flatMap((root) => gitFiles(repo, root)).filter((f) => !files.has(f));
}

export function drift(repo = REPO) {
  const files = plan(repo);
  const problems = [];
  const listPath = path.join(repo, LIST);
  if (!fs.existsSync(listPath)) problems.push(`${LIST} is missing`);
  else if (lf(fs.readFileSync(listPath)) !== listOf(files)) problems.push(`${LIST} does not name what the sources generate`);
  for (const [target, { source, content }] of files) {
    if (isLink(repo, target)) problems.push(`${target} is a link; a generated file is a copy`);
    else if (!isFile(repo, target)) problems.push(`${target} is missing (from ${[source].flat().join(', ')})`);
    else if (lf(fs.readFileSync(path.join(repo, target))) !== lf(content)) problems.push(`${target} differs from ${[source].flat().join(', ')}`);
  }
  for (const f of strays(repo, files)) problems.push(`${f} is not generated from anything; remove it or give it a source`);
  return problems;
}

// Write the plan. Remove only what the previous list named; refuse, naming it, anything else.
export function write(repo = REPO) {
  const files = plan(repo);
  const listPath = path.join(repo, LIST);
  const previous = fs.existsSync(listPath) ? Object.keys(JSON.parse(fs.readFileSync(listPath, 'utf8')).files ?? {}) : [];
  const unknown = strays(repo, files).filter((f) => !previous.includes(f));
  if (unknown.length) {
    return { ok: false, lines: unknown.map((f) => `${f} is under a generated directory, and nothing generated it; move it, or give it a source in .claude/. Nothing was written.`) };
  }
  const lines = [];
  for (const f of strays(repo, files)) { fs.rmSync(path.join(repo, f)); lines.push(`removed ${f}, which its source no longer generates`); }
  for (const [target, { content }] of files) {
    if (isLink(repo, target)) fs.rmSync(path.join(repo, target));
    fs.mkdirSync(path.dirname(path.join(repo, target)), { recursive: true });
    fs.writeFileSync(path.join(repo, target), content);
  }
  fs.writeFileSync(listPath, listOf(files));
  lines.push(`wrote ${files.size} files and ${LIST}`);
  return { ok: true, lines };
}

// Resolved on both sides: a checkout reached through a symlink must not skip the whole script.
const invoked = process.argv[1] && fs.existsSync(process.argv[1]) && fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url));
if (invoked) {
  if (process.argv.includes('--check')) {
    const problems = drift();
    for (const p of problems) console.error(`gen-agent-files: ${p}`);
    if (!problems.length) console.log('gen-agent-files: every generated file matches its source');
    process.exit(problems.length ? 1 : 0);
  }
  const { ok, lines } = write();
  for (const l of lines) (ok ? console.log : console.error)(`gen-agent-files: ${l}`);
  process.exit(ok ? 0 : 1);
}
